function svgText(p,text,size=12,align=0,color='#234c80'){return `<text x="${p[0]}" y="${-p[1]}" fill="${color}" stroke="none" font-size="${size}" font-family="Consolas, monospace" text-anchor="${align===1?'middle':align===2?'end':'start'}" dominant-baseline="auto">${esc(text)}</text>`;}
function arcPath(a,b,c){if(!a.length||!b.length||!c.length)return '';const [x1,y1]=[a[0],-a[1]],[x2,y2]=[c[0],-c[1]],[x3,y3]=[b[0],-b[1]],d=2*(x1*(y2-y3)+x2*(y3-y1)+x3*(y1-y2));if(Math.abs(d)<.001)return `M${x1},${y1} Q${x2},${y2} ${x3},${y3}`;const q1=x1*x1+y1*y1,q2=x2*x2+y2*y2,q3=x3*x3+y3*y3,cx=(q1*(y2-y3)+q2*(y3-y1)+q3*(y1-y2))/d,cy=(q1*(x3-x2)+q2*(x1-x3)+q3*(x2-x1))/d,r=Math.hypot(x1-cx,y1-cy),ang=(x,y)=>(Math.atan2(y-cy,x-cx)+Math.PI*2)%(Math.PI*2),a1=ang(x1,y1),a2=ang(x2,y2),a3=ang(x3,y3),dist=(a,b)=>(b-a+Math.PI*2)%(Math.PI*2),sweep=dist(a1,a2)<dist(a1,a3)?1:0,delta=sweep?dist(a1,a3):dist(a3,a1);return `M${x1},${y1} A${r},${r} 0 ${delta>Math.PI?1:0} ${sweep} ${x3},${y3}`;}
