function partBounds(c){const ps=pinsFor(c,data).map(p=>p.point);if(c.kind!=='GATE')ps.push([c.x-30,c.y-18],[c.x+30,c.y+18]);else{const sym=resolveSymbol(c,data);for(const g of sym?.graphics||[]){for(const k of ['StartPoint','EndPoint','ControlPoint','Position']){const p=values(g,k);if(p.length>=2)ps.push(localPoint(c,p));}const b=values(g,'BoundRect');if(b.length)ps.push(localPoint(c,[b[0],b[1]]),localPoint(c,[b[2],b[3]]));}}if(!ps.length)ps.push([c.x-40,c.y-30],[c.x+40,c.y+30]);return {x:Math.min(...ps.map(p=>p[0]))-8,y:Math.min(...ps.map(p=>p[1]))-8,w:Math.max(...ps.map(p=>p[0]))-Math.min(...ps.map(p=>p[0]))+16,h:Math.max(...ps.map(p=>p[1]))-Math.min(...ps.map(p=>p[1]))+16};}
