function renderLibrary(){const query=$('#search').value.trim().toUpperCase();let symbols=Object.values(data.symbols).filter(s=>{if(query&&!s.name.includes(query)&&!s.key.includes(query))return false;if(filter==='basic')return s.key.startsWith('SPARTAN/')&&basic.includes(s.name);if(filter==='all')return true;return s.key.startsWith(filter+'/');}).sort((a,b)=>filter==='basic'?basic.indexOf(a.name)-basic.indexOf(b.name):a.name.localeCompare(b.name));$('#symbol-count').textContent=data.statistics.symbols;$('#library-list').innerHTML=`<div class="library-category">${filter==='basic'?'LOGIC GATES':filter==='USER'?'PRACTICE CELLS':filter==='SPARTAN'?'SPARTAN LIBRARY':'ALL LIBRARIES'} · ${symbols.length}</div>`+symbols.map(s=>`<button class="component-button ${placing===s.key?'active':''}" data-symbol="${esc(s.key)}" title="${esc(s.key)}"><span class="component-icon"><svg viewBox="-75 -55 150 110"><g stroke="currentColor" fill="none" stroke-width="4">${symbolGraphics(s)}</g></svg></span><span class="component-copy"><b>${esc(s.name)}</b><small>${esc(description(s.name))}</small></span><span>+</span></button>`).join('');if(!symbols.length)$('#library-list').innerHTML+='<p class="empty-library">검색 결과가 없습니다.</p>';}
