const signals=[...inputPorts().map(c=>c.name),...outputPorts().map(c=>c.name)],samples=history.length?history:[{time:0,values:{...inputs,...result.outputs}}],w=Math.max($('#bottom-content').clientWidth,650),h=25+signals.length*27,step=(w-126)/Math.max(16,samples.length);let s=`<rect width="116" height="${h}" fill="#f8fafb"/><line x1="116" y1="0" x2="116" y2="${h}" stroke="#dbe4e9"/>`;
