function setMode(m,symbol=null){mode=m;placing=symbol;wireStart=null;wirePoints=[];$('#preview').innerHTML='';$('#canvas').classList.toggle('wiring',m==='wire');$('#canvas').classList.toggle('placing',m==='place'||m==='INPUT'||m==='OUTPUT');document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('#canvas-mode').textContent=m==='place'?symbol.split('/').at(-1):m.toUpperCase();$('#status').textContent=m==='wire'?'시작 핀 또는 배선을 클릭 → 경유점 클릭 → 도착 핀 클릭 · Esc 취소':m==='place'?'도면을 클릭해 '+symbol.split('/').at(-1)+' 배치 · Esc 종료':m==='INPUT'||m==='OUTPUT'?'도면을 클릭해 포트 배치':'준비 · 선택 및 이동';renderLibrary();}
