const snap=p=>p.map(v=>Math.round(v/10)*10);
function nearest(p){let best=null,dist=12*view.w/$('#canvas').clientWidth;for(const c of circuit.components)for(const pin of pinsFor(c,data)){const d=Math.hypot(p[0]-pin.point[0],p[1]-pin.point[1]);if(d<dist){best=pin.point;dist=d;}}if(best)return best;for(const w of circuit.wires)for(let i=1;i<w.points.length;i++){const a=w.points[i-1],b=w.points[i];const len=(b[0]-a[0])**2+(b[1]-a[1])**2;if(!len)continue;const t=Math.max(0,Math.min(1,((p[0]-a[0])*(b[0]-a[0])+(p[1]-a[1])*(b[1]-a[1]))/len)),q=[a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])],d=Math.hypot(p[0]-q[0],p[1]-q[1]);if(d<dist){best=snap(q);dist=d;}}return best;}
function route(a,b){if(a[0]===b[0]||a[1]===b[1])return [b];return [[b[0],a[1]],b];}
function nameFor(base){let n=base,i=0;while(circuit.components.some(c=>c.name===n))n=base+(++i);return n;}
function addPart(p){snapshot();const kind=mode==='place'?'GATE':mode,id='n'+sequence++;circuit.components.push({id,name:nameFor(kind==='GATE'?'I':kind==='INPUT'?'IN':'OUT'),kind,symbol:placing||'',x:p[0],y:p[1],rotation:0,portBubbles:[]});selection=id;commit();}
function moveComponent(c,x,y){const old=pinsFor(c,data).map(p=>p.point),dx=x-c.x,dy=y-c.y;c.x=x;c.y=y;for(const w of circuit.wires)for(const index of [0,w.points.length-1]){const p=w.points[index];if(!old.some(q=>q[0]===p[0]&&q[1]===p[1]))continue;const adjacent=index===0?1:index-1,neighbor=w.points[adjacent],next=[p[0]+dx,p[1]+dy];if(w.points.length===2){const other=w.points[1-index];const rt=route(next,other);w.points=index===0?[next,...rt]:[other,...route(other,next)];break;}if(neighbor[0]===p[0])neighbor[0]=next[0];else if(neighbor[1]===p[1])neighbor[1]=next[1];w.points[index]=next;}}
$('#canvas').addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;$('#canvas').focus();const p=point(e),q=nearest(p),target=e.target.closest('[data-component]'),wire=e.target.closest('[data-wire]');if(e.button===1||e.altKey){drag={type:'pan',start:p,view:{...view}};$('#canvas').setPointerCapture(e.pointerId);return;}
if(mode==='place'||mode==='INPUT'||mode==='OUTPUT'){addPart(snap(p));return;}
if(mode==='wire'||e.target.matches('[data-pin]')){if(mode!=='wire')setMode('wire');if(!wireStart){wireStart=q||snap(p);wirePoints=[wireStart];}else if(q){const points=[...wirePoints,...route(wirePoints.at(-1),q)].filter((p,i,a)=>!i||p[0]!==a[i-1][0]||p[1]!==a[i-1][1]);if(points.length>1){snapshot();circuit.wires.push({id:'w'+sequence++,points});commit();}wireStart=null;wirePoints=[];$('#preview').innerHTML='';}else wirePoints.push(...route(wirePoints.at(-1),snap(p)));return;}
if(target){selection=target.dataset.component;if(e.shiftKey){if(selectedIds.has(selection))selectedIds.delete(selection);else selectedIds.add(selection);}else if(!selectedIds.has(selection))selectedIds=new Set([selection]);const c=circuit.components.find(c=>c.id===selection);drag={type:'part',c,start:snap(p),x:c.x,y:c.y,original:clone(circuit),moved:false};$('#canvas').setPointerCapture(e.pointerId);}else if(wire){selection=wire.dataset.wire;selectedIds.clear();}else{selection=null;selectedIds.clear();drag={type:'pan',start:p,view:{...view}};$('#canvas').setPointerCapture(e.pointerId);}refresh();});
$('#canvas').addEventListener('pointermove',e=>{const p=point(e);$('#coords').textContent=`X: ${Math.round(p[0])}  Y: ${-Math.round(p[1])}`;if(drag?.type==='pan'){view.x-=p[0]-drag.start[0];view.y-=p[1]-drag.start[1];renderCanvas();return;}if(drag?.type==='part'){const q=snap(p),dx=q[0]-drag.start[0],dy=q[1]-drag.start[1];if(dx||dy)drag.moved=true;circuit=clone(drag.original);for(const c of circuit.components.filter(c=>selectedIds.has(c.id)))moveComponent(c,c.x+dx,c.y+dy);renderCanvas();return;}
if(mode==='place'||mode==='INPUT'||mode==='OUTPUT'){const q=snap(p);$('#preview').innerHTML=renderPart({id:'ghost',kind:mode==='place'?'GATE':mode,name:'',symbol:placing,x:q[0],y:q[1],rotation:0},true);}
if(wireStart){const q=nearest(p)||snap(p),pts=[...wirePoints,...route(wirePoints.at(-1),q)];$('#preview').innerHTML=`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#159a88" stroke-width="1.5" stroke-dasharray="4 3"/><circle cx="${q[0]}" cy="${q[1]}" r="4" fill="none" stroke="#159a88"/>`;}});
function endDrag(){if(drag?.type==='part'&&drag.moved){undo.push(JSON.stringify(drag.original));redo=[];commit();}drag=null;}
$('#canvas').addEventListener('pointerup',endDrag);$('#canvas').addEventListener('pointercancel',endDrag);
$('#canvas').addEventListener('dblclick',e=>{if(mode==='wire'&&wireStart){const p=snap(point(e)),pts=[...wirePoints,...route(wirePoints.at(-1),p)].filter((p,i,a)=>!i||p[0]!==a[i-1][0]||p[1]!==a[i-1][1]);if(pts.length>1){snapshot();circuit.wires.push({id:'w'+sequence++,points:pts});commit();}wireStart=null;wirePoints=[];$('#preview').innerHTML='';return;}const c=circuit.components.find(c=>c.id===e.target.closest('[data-component]')?.dataset.component);if(c?.kind==='INPUT')toggleInput(c.name,1-(inputs[c.name]??0));else if(c?.kind==='GATE'){const sub=data.circuits[c.symbol.split('/').at(-1)];if(sub)loadCircuit(sub);}});
function zoom(f,p=null){const center=p||[view.x+view.w/2,view.y+view.h/2],w=Math.max(80,Math.min(12000,view.w*f)),ratio=w/view.w;view={x:center[0]-(center[0]-view.x)*ratio,y:center[1]-(center[1]-view.y)*ratio,w,h:view.h*ratio};renderCanvas();$('#zoom-label').textContent=Math.round($('#canvas').clientWidth/view.w*100)+'%';}
$('#canvas').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:1/1.12,point(e));},{passive:false});
function toggleInput(n,v){inputs[n]=v;time+=10;evaluate(true);refresh();}
function loadCircuit(c){stop();snapshot();circuit=clone(c);selection=null;selectedIds.clear();inputs={};stimulus={};setMode('select');commit();fit();toast(circuit.name+' 회로를 열었습니다.');}
function stop(){if(running)clearInterval(running);running=null;$('#run-button').innerHTML='▶<span>시뮬레이션</span>';}
function step(){time+=10;inputPorts().forEach((c,i)=>{const setting=stimulus[c.name]||{step:10*2**i,values:[0,1],start:0,end:1000};if(time>=setting.start&&time<=setting.end)inputs[c.name]=setting.values[Math.floor((time-setting.start)/setting.step)%setting.values.length];});evaluate(true);refresh();}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function selectedParts(){return circuit.components.filter(c=>selectedIds.has(c.id)||c.id===selection);}
function shapeChange(kind){const parts=selectedParts().filter(c=>c.kind==='GATE');if(!parts.length)return;snapshot();for(const c of parts){const before=pinsFor(c,data);if(kind==='left')c.rotation=((c.rotation||0)+270)%360;else if(kind==='right')c.rotation=((c.rotation||0)+90)%360;else if(kind==='horizontal')c.mirror=!c.mirror;else{c.mirror=!c.mirror;c.rotation=((c.rotation||0)+180)%360;}const after=pinsFor(c,data);for(const w of circuit.wires)for(const idx of [0,w.points.length-1]){const i=before.findIndex(p=>p.point[0]===w.points[idx][0]&&p.point[1]===w.points[idx][1]);if(i>=0){const other=idx===0?w.points[1]:w.points[idx-1],end=after[i].point;if(idx===0)w.points=[end,...route(end,other),...w.points.slice(2)];else w.points=[...w.points.slice(0,-1),...route(other,end)];}}}commit();}
function alignParts(kind){const parts=selectedParts();if(parts.length<2){toast('Shift + 클릭으로 두 부품 이상을 선택하세요.');return;}snapshot();const xs=parts.map(c=>c.x),ys=parts.map(c=>c.y),horizontal=kind==='left'||kind==='right'||kind==='across';if(kind==='across'||kind==='down'){const sorted=parts.sort((a,b)=>horizontal?a.x-b.x:a.y-b.y),lo=horizontal?Math.min(...xs):Math.min(...ys),hi=horizontal?Math.max(...xs):Math.max(...ys);sorted.forEach((c,i)=>{const v=Math.round((lo+(hi-lo)*i/(sorted.length-1))/10)*10;moveComponent(c,horizontal?v:c.x,horizontal?c.y:v);});}else{const v=kind==='left'?Math.min(...xs):kind==='right'?Math.max(...xs):kind==='top'?Math.min(...ys):Math.max(...ys);parts.forEach(c=>moveComponent(c,horizontal?v:c.x,horizontal?c.y:v));}commit();}
function showModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function showExamples(){showModal('원본 실습 회로 열기',`<p class="modal-intro">폴더의 MyLogic 회로 10개를 원본 부품과 배선 좌표로 불러왔습니다. 회로를 클릭하면 편집 도면에 열립니다. 현재 회로는 JSON으로 저장할 수 있습니다.</p><div class="examples-grid">${Object.values(data.circuits).map((c,i)=>`<button class="example-card" data-example="${esc(c.name.toUpperCase())}"><span class="example-num">EXERCISE ${String(i+1).padStart(2,'0')}</span><b>${esc(c.name)}</b><small>${esc(names[c.name.toUpperCase()]||'논리회로 실습')}<br>${c.components.filter(c=>c.kind==='GATE').length} 게이트 · ${c.wires.length} 배선</small></button>`).join('')}</div>`);}
function showStimulus(){const text='[MyLogic STIMULUS V3.5]\nMAX_TIME 1000;\n'+inputPorts().map((c,i)=>{const s=stimulus[c.name]||{step:10*2**i,start:0,end:1000,values:[0,1]};return `CLOCK ${c.name} FROM : ${s.start} TO : ${s.end} STEPSIZE : ${s.step} ${s.values.join(' ')};`;}).join('\n')+'\nWATCH '+[...inputPorts(),...outputPorts()].map(c=>c.name).join(' ')+';';showModal('시뮬레이션 입력 설정',`<p class="modal-intro">원본 STIM.STM의 CLOCK, MAX_TIME 문법을 사용합니다. 한 단계는 10 ns이며 실행 중 각 입력의 CLOCK 패턴을 적용합니다. GEN, VECTOR 문법은 현재 지원하지 않습니다.</p><textarea class="stimulus-editor" id="stimulus-text" spellcheck="false">${esc(text)}</textarea><button class="modal-primary" id="apply-stimulus">적용</button><button class="modal-primary" id="export-stimulus" style="margin-right:8px">STIM.STM 저장</button><div style="clear:both"></div>`);$('#apply-stimulus').onclick=()=>{try{const t=$('#stimulus-text').value,newSettings={},re=/CLOCK\s+(\S+)\s+FROM\s*:\s*(\d+)\s+TO\s*:\s*(\d+)\s+STEPSIZE\s*:\s*(\d+)\s+([01\s]+);/gi;let m;while((m=re.exec(t))){if(!inputPorts().some(c=>c.name===m[1]))throw Error('존재하지 않는 입력: '+m[1]);const s={start:+m[2],end:+m[3],step:+m[4],values:m[5].trim().split(/\s+/).map(Number)};if(!s.step||s.end<s.start)throw Error('CLOCK 시간 범위를 확인하세요.');newSettings[m[1]]=s;}if(/\b(GEN|VECTOR)\b/i.test(t))throw Error('GEN, VECTOR 문법은 지원하지 않습니다. CLOCK을 사용하세요.');if((t.match(/\bCLOCK\b/gi)||[]).length!==Object.keys(newSettings).length)throw Error('CLOCK 문법을 확인하세요.');stimulus=newSettings;stimulus.maxTime=Number(t.match(/MAX_TIME\s+(\d+)/i)?.[1]||1000);if(stimulus.maxTime<10)throw Error('MAX_TIME은 10 이상이어야 합니다.');time=0;history=[];state={};clocks={};$('#modal').close();refresh();toast('입력 패턴을 적용했습니다.');}catch(e){toast(e.message);}};$('#export-stimulus').onclick=()=>download('stim.stm',$('#stimulus-text').value,'text/plain');}
const actions={ signals(){const shown=$('.inspector').classList.toggle('show-inspector');$('.signals-button').textContent=shown?'입출력 ◂':'입출력 ▸';},
 new(){stop();snapshot();circuit={name:'Untitled',library:'User',components:[],wires:[],notes:[]};selection=null;inputs={};setMode('select');commit();fit();},
 import(){$('#file-input').click();},save(){download(circuit.name+'.mylogic.json',JSON.stringify({format:'MyLogic-Web-1',...circuit},null,2));dirty=false,truthCache=null;toast('회로 파일을 저장했습니다.');},
 undo(){if(!undo.length)return;stop();redo.push(JSON.stringify(circuit));circuit=JSON.parse(undo.pop());selection=null;commit();},redo(){if(!redo.length)return;stop();undo.push(JSON.stringify(circuit));circuit=JSON.parse(redo.pop());selection=null;commit();},
 delete(){if(!selection&&!selectedIds.size)return;snapshot();circuit.components=circuit.components.filter(c=>c.id!==selection&&!selectedIds.has(c.id));circuit.wires=circuit.wires.filter(w=>w.id!==selection);selection=null;selectedIds.clear();commit();},
 rotate(){shapeChange('right');},rotateleft(){shapeChange('left');},fliph(){shapeChange('horizontal');},flipv(){shapeChange('vertical');},
 alignleft(){alignParts('left');},alignright(){alignParts('right');},aligntop(){alignParts('top');},alignbottom(){alignParts('bottom');},spaceacross(){alignParts('across');},spacedown(){alignParts('down');},
 selectall(){selectedIds=new Set(circuit.components.map(c=>c.id));selection=circuit.components[0]?.id;refresh();},copy(){clipboardParts=clone(selectedParts());toast(clipboardParts.length+'개 부품을 복사했습니다.');},cut(){actions.copy();actions.delete();},paste(){if(!clipboardParts.length)return;snapshot();selectedIds.clear();for(const part of clipboardParts){const c=clone(part);c.id='n'+sequence++;c.name=nameFor(c.kind==='GATE'?'I':c.name);c.x+=40;c.y+=40;circuit.components.push(c);selectedIds.add(c.id);}selection=[...selectedIds][0];commit();},
 check(){bottom='diagnostics';document.querySelectorAll('[data-bottom]').forEach(b=>b.classList.toggle('active',b.dataset.bottom===bottom));renderBottom();},find(){$('#search').focus();},properties(){if(innerWidth<=850)actions.signals();$('#prop-name')?.focus();},
 duplicate(){const c=circuit.components.find(c=>c.id===selection);if(!c)return;snapshot();const copy=clone(c);copy.id='n'+sequence++;copy.name=nameFor(c.kind==='GATE'?'I':c.name);copy.x+=30;copy.y+=30;circuit.components.push(copy);selection=copy.id;commit();},
 fit,zoomin(){zoom(1/1.2);},zoomout(){zoom(1.2);},grid(){grid=!grid;$('#grid-button').classList.toggle('active',grid);renderCanvas();},step,
 run(){if(running){stop();return;}$('#run-button').innerHTML='Ⅱ<span>일시 정지</span>';running=setInterval(()=>{if(time>=(stimulus.maxTime||1000)){stop();toast('설정된 시뮬레이션 시간이 완료되었습니다.');return;}step();},350);step();},
 reset(){stop();time=0;inputs={};state={};clocks={};history=[];refresh();},examples:showExamples,stimulus:showStimulus,
 csv(){try{const t=truthTable(circuit,data),cols=[...t.inputs,...t.outputs];download(circuit.name+'.csv','\ufeff'+[cols.join(','),...t.rows.map(r=>cols.map(n=>r[n]).join(','))].join('\r\n'),'text/csv;charset=utf-8');}catch(e){toast(e.message);}},
 svg(){const padding=20,bounds=circuit.components.map(partBounds),ps=[...bounds.flatMap(b=>[[b.x,b.y],[b.x+b.w,b.y+b.h]]),...circuit.wires.flatMap(w=>w.points)];if(!ps.length)return;const minx=Math.min(...ps.map(p=>p[0]))-padding,miny=Math.min(...ps.map(p=>p[1]))-padding,w=Math.max(...ps.map(p=>p[0]))-minx+padding,h=Math.max(...ps.map(p=>p[1]))-miny+padding;const dom=$('#drawing').cloneNode(true);dom.querySelectorAll('.pin-hit,.selection-box').forEach(n=>n.remove());download(circuit.name+'.svg',`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${minx} ${miny} ${w} ${h}" width="${w*2}" height="${h*2}"><rect x="${minx}" y="${miny}" width="${w}" height="${h}" fill="white"/>${dom.outerHTML}</svg>`,'image/svg+xml');},
 help(){showModal('MyLogic Web 사용 방법',`<p class="modal-intro">MyLogic SV5.1의 원본 회로와 600개 심벌을 기반으로 만든 웹 회로 편집기입니다. 원본 프로그램과 모든 기능이 동일한 버전은 아닙니다.</p><div class="help-grid"><section><h3>회로 편집</h3><p>왼쪽 부품 선택 → 도면 클릭으로 배치합니다.<br><kbd>V</kbd> 선택 · 드래그 이동<br><kbd>W</kbd> 배선 · 시작 핀 → 경유점 → 도착 핀<br>기존 배선에 클릭해 분기할 수 있습니다.<br>빈 위치에 배선을 끝내려면 더블클릭합니다.<br><kbd>R</kbd> 90° 회전 · <kbd>Delete</kbd> 삭제<br><kbd>Esc</kbd> 배치 및 배선 종료<br><kbd>Ctrl Z</kbd> 실행 취소 · <kbd>Ctrl Y</kbd> 다시 실행<br>포트를 더블클릭하면 입력이 전환됩니다.</p></section><section><h3>도면과 파일</h3><p>휠로 확대 · 빈 도면 드래그로 이동합니다.<br><kbd>F</kbd> 전체 보기 · <kbd>Alt</kbd> + 드래그로 이동<br><kbd>Ctrl S</kbd> 웹 회로 JSON 저장<br><kbd>Ctrl O</kbd> JSON 또는 원본 schematic 열기<br>File 메뉴에서 SVG로 도면을 내보냅니다.<br>실습 셀을 더블클릭하면 내부 회로를 엽니다.<br>자동 저장은 현재 브라우저에 저장됩니다.<br>원본 schematic은 가져오기만 지원합니다.</p></section><section><h3>시뮬레이션</h3><p>입력 스위치를 누르면 출력이 즉시 계산됩니다.<br>Step은 10 ns씩 CLOCK 패턴을 실행합니다.<br>진리표는 입력 10개까지 생성합니다.<br>회로 검사에서 미지원 모델과 배선 오류를 확인합니다.<br>AND, OR, XOR, NOT, NAND, NOR, XNOR,<br>BUF, 전원, MUX, 기본 D 플립플롭과<br>첨부된 계층 실습 회로를 지원합니다.</p></section><section><h3>재현 범위</h3><p>원본 배선 좌표, 게이트 심벌, 실습 회로를 사용합니다.<br>입력 CLOCK 설정과 파형, 진리표를 제공합니다.<br>MySim의 지연·타이밍 검사, HDL 컴파일,<br>FPGA 배치·배선, 모든 순차·메모리 소자의<br>모델은 아직 구현되지 않았습니다.<br>미지원 소자는 X로 표시합니다.<br>라이브러리의 모든 부품이 시뮬레이션되는 것은 아닙니다.</p></section></div>`);}
};
const menus={file:[['new','새 회로','Ctrl+N'],['import','회로 열기','Ctrl+O'],['save','회로 저장','Ctrl+S'],['svg','도면 SVG 내보내기',''],['csv','진리표 CSV 내보내기','']],edit:[['undo','실행 취소','Ctrl+Z'],['redo','다시 실행','Ctrl+Y'],['duplicate','선택 부품 복제','Ctrl+D'],['rotate','90° 회전','R'],['delete','삭제','Delete']],view:[['fit','회로 전체 보기','F'],['zoomin','확대','+'],['zoomout','축소','−'],['grid','격자 표시 / 숨기기','']],draw:[['mode:select','선택 및 이동','V'],['mode:wire','배선','W'],['mode:INPUT','입력 포트',''],['mode:OUTPUT','출력 포트','']],simulate:[['run','실행 / 일시 정지','Space'],['step','한 단계 실행',''],['reset','초기화',''],['stimulus','입력 CLOCK 설정','']]};
Object.assign(menus,{shape:[['rotateleft','Rotate Left · 왼쪽 회전','L'],['rotate','Rotate Right · 오른쪽 회전','R'],['flipv','Flip Vertical · 상하 대칭','Y'],['fliph','Flip Horizontal · 좌우 대칭','X']],layout:[['alignleft','Align Left · 왼쪽 정렬','Ctrl+←'],['alignright','Align Right · 오른쪽 정렬','Ctrl+→'],['aligntop','Align Top · 위쪽 정렬','Ctrl+↑'],['alignbottom','Align Bottom · 아래쪽 정렬','Ctrl+↓'],['spaceacross','Space Across · 가로 간격','Alt+→'],['spacedown','Space Down · 세로 간격','Alt+↑']],window:[['examples','Open Schematic · 실습 회로',''],['properties','Properties · 속성','Alt+Enter'],['fit','Whole Page · 전체 보기','Home']]});
menus.edit.splice(2,0,['cut','Cut · 잘라내기','Ctrl+X'],['copy','Copy · 부품 복사','Ctrl+C'],['paste','Paste · 부품 붙여넣기','Ctrl+V'],['selectall','Select All · 전체 선택','Ctrl+A'],['find','Find · 부품 검색','Ctrl+F']);menus.simulate.unshift(['check','Check Circuit · 회로 검사','Ctrl+E']);menus.simulate[1]=['run','Simulator · 실행 / 일시 정지','F5'];
document.addEventListener('click',e=>{const menu=e.target.closest('[data-menu]');if(menu){const rect=menu.getBoundingClientRect();$('#dropdown').innerHTML=menus[menu.dataset.menu].map(([action,label,kbd])=>`<button data-action="${action}">${label}<kbd>${kbd}</kbd></button>`).join('');$('#dropdown').style.left=rect.left+'px';$('#dropdown').style.top=rect.bottom+'px';$('#dropdown').hidden=!$('#dropdown').hidden&&$('#dropdown').dataset.current===menu.dataset.menu;$('#dropdown').dataset.current=menu.dataset.menu;return;}$('#dropdown').hidden=true;const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action.startsWith('mode:'))setMode(action.slice(5));else actions[action]?.();}const m=e.target.closest('[data-mode]');if(m)setMode(m.dataset.mode);const s=e.target.closest('[data-symbol]');if(s)setMode('place',s.dataset.symbol);const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===f));renderLibrary();}const inp=e.target.closest('[data-input]');if(inp)toggleInput(inp.dataset.input,Number(inp.dataset.value));const tab=e.target.closest('[data-bottom]');if(tab){bottom=tab.dataset.bottom;document.querySelectorAll('[data-bottom]').forEach(b=>b.classList.toggle('active',b===tab));renderBottom();}const example=e.target.closest('[data-example]');if(example){$('#modal').close();loadCircuit(data.circuits[example.dataset.example]);}});
$('#search').addEventListener('input',renderLibrary);$('#modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let imported;if(file.name.endsWith('.json')||file.name.endsWith('.mylogic'))imported=JSON.parse(await file.text());else{const bytes=await file.arrayBuffer();imported=decodeCircuit(new TextDecoder('euc-kr').decode(bytes));}if(!Array.isArray(imported.components)||!Array.isArray(imported.wires)||!imported.components.every(c=>typeof c.id==='string'&&['INPUT','OUTPUT','GATE'].includes(c.kind)&&Number.isFinite(c.x)&&Number.isFinite(c.y)&&(c.kind!=='GATE'||typeof c.symbol==='string'))||!imported.wires.every(w=>typeof w.id==='string'&&Array.isArray(w.points)&&w.points.length>=2&&w.points.every(p=>p.length===2&&p.every(Number.isFinite))))throw Error('지원하지 않거나 손상된 회로 파일입니다.');loadCircuit(imported);}catch(err){toast('파일 열기 실패: '+err.message);}finally{e.target.value='';}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open)return;const k=e.key.toLowerCase();if(e.ctrlKey||e.metaKey){const a={s:'save',o:'import',n:'new',z:e.shiftKey?'redo':'undo',y:'redo',d:'duplicate',a:'selectall',c:'copy',v:'paste',x:'cut',f:'find',e:'check',arrowleft:'alignleft',arrowright:'alignright',arrowup:'aligntop',arrowdown:'alignbottom'}[k];if(a){e.preventDefault();actions[a]();}return;}if(e.altKey){const a={arrowright:'spaceacross',arrowup:'spacedown',enter:'properties'}[k];if(a){e.preventDefault();actions[a]();return;}}if(k==='escape'){setMode('select');selection=null;selectedIds.clear();refresh();}else if(k==='v')setMode('select');else if(k==='w'||k==='n')setMode('wire');else if(k==='r')actions.rotate();else if(k==='l')actions.rotateleft();else if(k==='x')actions.fliph();else if(k==='y')actions.flipv();else if(k==='f'||k==='home')fit();else if(k==='delete'||k==='backspace'){e.preventDefault();actions.delete();}else if(k===' '||k==='f5'){e.preventDefault();actions.run();}else if(k==='+'||k==='=')actions.zoomin();else if(k==='-')actions.zoomout();});
new ResizeObserver(()=>{const aspect=$('#canvas').clientWidth/Math.max(1,$('#canvas').clientHeight);view.w=view.h*aspect;renderCanvas();renderBottom();}).observe($('#canvas-wrap'));
graph=compile(circuit,data);evaluate();renderLibrary();refresh();fit();$('#status').textContent='준비 · 원본 라이브러리 600개 / 실습 회로 10개';
